import React, { useState } from "react";
import axios from "axios";
import "./ArtistRegistration.css"; // optional if you want styling

function ArtistRegistration() {
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    stageName: "",
    bio: "",
    password: "",
  });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post("http://localhost:5000/artists/register", formData);
      alert(res.data.message || "Registration successful! Pending approval.");
      setFormData({
        firstName: "",
        lastName: "",
        email: "",
        stageName: "",
        bio: "",
        password: "",
      });
    } catch (err) {
      console.error(err);
      alert("Error registering artist. Try again.");
    }
  };

  return (
    <div className="register-container">
      <h2>Register as an Artist</h2>
      <form onSubmit={handleSubmit} className="register-form">
        <input
          type="text"
          name="firstName"
          placeholder="First Name"
          value={formData.firstName}
          onChange={handleChange}
          required
        />
        <input
          type="text"
          name="lastName"
          placeholder="Last Name"
          value={formData.lastName}
          onChange={handleChange}
          required
        />
        <input
          type="email"
          name="email"
          placeholder="Email"
          value={formData.email}
          onChange={handleChange}
          required
        />
        <input
          type="text"
          name="stageName"
          placeholder="Stage Name"
          value={formData.stageName}
          onChange={handleChange}
          required
        />
        <textarea
          name="bio"
          placeholder="Short Bio"
          value={formData.bio}
          onChange={handleChange}
          required
        />
        <input
          type="password"
          name="password"
          placeholder="Password"
          value={formData.password}
          onChange={handleChange}
          required
        />
        <button type="submit">Register</button>
      </form>
    </div>
  );
}

export default ArtistRegistration;
